import os
import requests

def extract_layout(payload, config=None):
    config = config or {}
    endpoint = config.get("endpoint", "https://api.ocr.space/parse/image")
    api_key = config.get("api_key") or os.environ["OCR_SPACE_API_KEY"]
    data = {
        "apikey": api_key,
        "OCREngine": str(config.get("ocr_engine", 2)),
        "isTable": str(config.get("is_table", True)).lower(),
        "detectOrientation": str(config.get("detect_orientation", True)).lower(),
        "scale": str(config.get("scale", True)).lower(),
        "isCreateSearchablePdf": str(config.get("create_searchable_pdf", False)).lower(),
    }
    files = None

    if isinstance(payload, (bytes, bytearray)):
        files = {"file": (config.get("filename", "document.bin"), payload)}
    elif isinstance(payload, str):
        if payload.startswith("http://") or payload.startswith("https://"):
            data["url"] = payload
        elif os.path.exists(payload):
            files = {"file": (os.path.basename(payload), open(payload, "rb"))}
        else:
            data["base64Image"] = payload
    elif hasattr(payload, "read"):
        files = {"file": (getattr(payload, "name", config.get("filename", "document.bin")), payload)}
    else:
        raise TypeError("payload must be bytes, a file path, a URL, a base64 string, or a file-like object")

    try:
        response = requests.post(endpoint, data=data, files=files, timeout=config.get("timeout", 120))
        response.raise_for_status()
        parsed = response.json()
    finally:
        if files and isinstance(payload, str) and os.path.exists(payload):
            files["file"][1].close()

    parsed_results = parsed.get("ParsedResults", [])
    text_overlay = parsed_results[0].get("TextOverlay", {}) if parsed_results else {}
    result = {
        "provider": "ocr.space",
        "raw": parsed,
        "blocks": text_overlay.get("Lines", []),
        "lines": [
            {
                "text": line.get("LineText", ""),
                "words": line.get("Words", []),
                "max_height": line.get("MaxHeight"),
                "min_top": line.get("MinTop"),
            }
            for line in text_overlay.get("Lines", [])
        ],
        "tables_detected": bool(config.get("is_table", True)),
        "text": "\n".join(
            line.get("LineText", "") for line in text_overlay.get("Lines", [])
        ),
    }
    return result
